steps.command:
grep -rn "_get_all_criterion\|_process_criteria\|oval_parser" src tests | grep -v "^src/vunnel/providers/oracle/oval_parser.py"; python3 - <<'E'
s=open('schema/vulnerability/os/schema-1.1.0.json').read()
old='''                "Module": {
                  "type": ["string", "null"]
                }
'''
assert s.count(old)==1
s=s.replace(old,'''                "Module": {
                  "type": ["string", "null"]
                },
                "Arch": {
                  "type": "string",
                  "description": "CPU architecture this fix version applies to (omitted when the fix applies to all architectures)"
                }
''')
s=s.replace('schema-1.1.0.json','schema-1.1.1.json')
open('schema/vulnerability/os/schema-1.1.1.json','w').write(s)
E
grep -n '"\$id"\|1\.1\.' schema/vulnerability/os/schema-1.1.1.json

python3 - <<'E'
p='src/vunnel/providers/oracle/oval_parser.py'
s=open(p).read()
a=s.index('    all_arches = {e[2]')
b=s.index('def _process_criteria(')
s=s[:a]+'''    all_arches = {e[2] for e in entries if e[2]}
    by_pkg: dict[tuple, dict[str, set]] = {}
    for pkg, version, arch, module in entries:
        by_pkg.setdefault((pkg, module), {}).setdefault(version, set()).add(arch)

    result = set()
    for (pkg, module), versions in by_pkg.items():
        # every version ships for every arch (or arch is unknown): no arch differentiation for this package
        shared = all(None in arches or arches == all_arches for arches in versions.values())
        for version, arches in versions.items():
            if shared:
                result.add((pkg, version, None, module))
            else:
                result.update((pkg, version, a, module) for a in (all_arches if None in arches else arches))

    return sorted(result, key=lambda r: (r[0], r[1], r[2] or "", r[3] or ""))


'''+s[b:]
open(p,'w').write(s)
E
.venv/bin/python -m pytest -q tests/unit 2>&1 | tail -15; .venv/bin/python -m mypy src/vunnel | tail -3
